MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'LAH-8085'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-4801B'})
MATCH (p)-[:line_to*1..]->(v:Valve)
WHERE EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'P-2501A'})-[:measured_by]->(i:PlantItem)
