MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LSHH-44004'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-401'}), (b:PlantItem {tag: 'P-504'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'CHV-4001' AND y.tag <> 'CHV-4001')+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (source:PlantItem {tag: 'P-1601'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
