MATCH (e:PlantItem {tag: 'H-4001'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-5501B'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'V-3301'}), (b:PlantItem {tag: 'V-3801'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'BFV-34001' AND y.tag <> 'BFV-34001')+ (b)
       } AS reachable_without_bfv34001

MATCH (p:PlantItem {tag: 'P-5602A'})-[:line_to*1..]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(s:PlantItem), (s)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'TIAH-26006'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (h:PlantItem {tag: 'H-4001'}), (e:PlantItem {tag: 'V-4001'}), (v:Valve)
WHERE EXISTS { (h)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(f:PlantItem {loop_tag: 'LIC-27029'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem:Valve {tag: 'V-3701'})-[:line_to*1..]->(valve:PlantItem:Valve)
WHERE EXISTS { (valve)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem {tag: 'V-2101'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (i:PlantItem {tag: 'PI-48023'})-[:is_located_in]->(u:PlantSection)
RETURN DISTINCT u.unit_id AS unit_id
ORDER BY unit_id;

MATCH (v:Valve)-[:line_to*1..]->(:PlantItem {tag: 'P-3901B'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-102'}), (b:PlantItem {tag: 'P-101'}), (blocked:PlantItem {tag: 'GTV-1022'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((n:PlantItem)-[:line_to]->(m:PlantItem) WHERE n <> blocked)* (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'TK-5303'}), (b:PlantItem {tag: 'TK-5304'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;
